import sys,os,json,hashlib,subprocess,platform,datetime,importlib.metadata,importlib
from pathlib import Path
R=Path('/home/student20261/workdir/GPAT_TransferBench'); E=Path(sys.prefix)
def run(a):
 p=subprocess.run(a,capture_output=True,text=True); return {'argv':a,'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
def fingerprint():
 rows=[]; meta={}
 for base,dirs,files in os.walk(E):
  for name in sorted(dirs+files):
   p=Path(base)/name; s=p.lstat(); rel=str(p.relative_to(E))
   rows.append([rel,s.st_mode,s.st_size,s.st_mtime_ns,os.readlink(p) if p.is_symlink() else None])
   if p.is_file() and (rel.startswith('conda-meta/') or ('.dist-info/' in rel and name in ['METADATA','RECORD','INSTALLER','direct_url.json'])): meta[rel]=hashlib.sha256(p.read_bytes()).hexdigest()
 b=json.dumps(sorted(rows),separators=(',',':')).encode()
 return {'entries':len(rows),'metadata_tree_sha256':hashlib.sha256(b).hexdigest(),'package_metadata_sha256':hashlib.sha256(json.dumps(meta,sort_keys=True).encode()).hexdigest(),'package_metadata_files':len(meta)}
before=fingerprint()
facts={k:run(v) for k,v in {'gpu':['nvidia-smi','--query-gpu=name,driver_version,compute_cap,memory.total','--format=csv,noheader'],'nvcc':['nvcc','--version'],'kernel':['uname','-a'],'glibc':['getconf','GNU_LIBC_VERSION'],'conda':['/home/student20261/miniconda3/bin/conda','--version']}.items()}
facts['os_release']=Path('/etc/os-release').read_text(); facts['machine']=platform.machine()
versions={'python':platform.python_version()}
for n in ['tensorflow','torch','torchvision','numpy','keras','protobuf','scipy','matplotlib','Pillow','opencv-python']:
 try: versions[n]=importlib.metadata.version(n)
 except importlib.metadata.PackageNotFoundError: versions[n]=None
blocked=[]; temporary_writes=[]
def guard(event,args):
 if event=='open' and isinstance(args[0],(str,bytes)):
  p=Path(os.fsdecode(args[0])).absolute(); flags=args[2] if isinstance(args[2],int) else 0
  if 'GPAT_TransferBench_runtime' in p.parts or p.is_relative_to(R/'manifests') or p.is_relative_to(R/'data') or p.is_relative_to(R/'third_party/source_cache'):
   blocked.append([event,str(p)]); raise RuntimeError('scientific/source data open forbidden')
  if flags & (os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC|os.O_APPEND):
   if str(p)=='/dev/null' or p.is_relative_to('/tmp'): temporary_writes.append([event,str(p)])
   else: blocked.append([event,str(p)]); raise RuntimeError('persistent writes forbidden')
 if event in ['os.mkdir','os.remove','os.rmdir','os.rename','os.chmod','os.chown','os.symlink','os.link','os.truncate']:
  paths=[x for x in args[:2] if isinstance(x,(str,bytes))]
  if any(not Path(os.fsdecode(x)).absolute().is_relative_to('/tmp') for x in paths):
   blocked.append([event,str(paths)]); raise RuntimeError('persistent mutation forbidden')
  temporary_writes.append([event,str(paths)])
sys.addaudithook(guard)
probe={}
try:
 import tensorflow as tf
 probe['tensorflow']={'available':True,'version':tf.__version__}
 for name in ['Session','ConfigProto','GPUOptions','py_func','train.AdamOptimizer','image.resize_images','ensure_shape','contrib','set_random_seed']:
  obj=tf
  try:
   for part in name.split('.'): obj=getattr(obj,part)
   probe[name]={'available':True}
  except Exception as ex: probe[name]={'available':False,'error':type(ex).__name__+': '+str(ex)}
 try: importlib.import_module('tensorflow.contrib'); probe['tensorflow.contrib']={'available':True}
 except Exception as ex: probe['tensorflow.contrib']={'available':False,'error':type(ex).__name__+': '+str(ex)}
 probe['build_info']=tf.sysconfig.get_build_info()
except Exception as ex: probe['tensorflow']={'available':False,'error':type(ex).__name__+': '+str(ex)}
after=fingerprint()
print(json.dumps({'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'environment':str(E),'versions':versions,'host':facts,'probe':probe,'environment_before':before,'environment_after':after,'environment_unchanged':before==after,'guard':{'blocked':blocked,'temporary_writes':temporary_writes,'scope':'Python audit hooks; not a syscall sandbox. No framework tensor/session/model or device enumeration APIs called.'}},sort_keys=True))

