import urllib.request,json,hashlib,pathlib,concurrent.futures,re
src=pathlib.Path('/home/cong/GPAT_TransferBench/third_party/source_cache/stdn')
api={}
for p in sorted(src.rglob('*.py')):
 for n,l in enumerate(p.read_text().splitlines(),1):
  for s in re.findall(r'\b(?:tf|layers)\.[A-Za-z_][\w.]*',l):
   s=s.replace('layers.','tf.contrib.layers.',1) if s.startswith('layers.') else s
   api.setdefault(s,[]).append({'file':str(p.relative_to(src)),'line':n,'text':l.strip()})
urls=[]
for v in ['1.11.0','1.12.0','1.13.1','1.15.0']:
 for mod in ['tensorflow','tensorflow.random','tensorflow.math','tensorflow.initializers','tensorflow.image','tensorflow.train','tensorflow.contrib.layers','tensorflow.contrib.framework']:
  urls.append(f'https://raw.githubusercontent.com/tensorflow/tensorflow/v{v}/tensorflow/tools/api/golden/v1/{mod}.pbtxt')
urls += ['https://raw.githubusercontent.com/NVIDIA/tensorflow/r1.15.5%2Bnv23.03/tensorflow/contrib/layers/python/layers/layers.py','https://raw.githubusercontent.com/NVIDIA/tensorflow/r1.15.5%2Bnv23.03/tensorflow/python/ops/check_ops.py','https://raw.githubusercontent.com/tensorflow/tensorflow/v1.10.0/tensorflow/tools/api/golden/tensorflow.pbtxt','https://raw.githubusercontent.com/tensorflow/tensorflow/v1.9.0/tensorflow/tools/api/golden/tensorflow.pbtxt']
def get(u):
 try:
  with urllib.request.urlopen(u,timeout=30) as r: b=r.read()
  t=b.decode(); names=re.findall(r'name: "(.*?)"',t)
  return {'url':u,'http_status':200,'sha256':hashlib.sha256(b).hexdigest(),'export_names':names,'key_definitions':[{'line':i,'text':s} for i,s in enumerate(t.splitlines(),1) if re.search(r'^def (ensure_shape|convolution2d|batch_norm|avg_pool2d|conv2d_transpose)',s)]}
 except Exception as e:return {'url':u,'error':repr(e)}
q=list(concurrent.futures.ThreadPoolExecutor(max_workers=8).map(get,urls))
pathlib.Path('/tmp/m6d2a_api_metadata.json').write_text(json.dumps({'source_api_inventory':api,'queries':q},indent=2))
for r in q:
 print(r['url'],r.get('error','OK'), {x:x in r.get('export_names',[]) for x in ['ensure_shape','uniform','reduce_mean']} if '.pbtxt' in r['url'] else r.get('key_definitions'))

