import urllib.request,urllib.error,json,hashlib,concurrent.futures,pathlib,datetime
urls=[f'https://pypi.org/pypi/{p}/json' for p in ['tensorflow','tensorflow-gpu']]
urls += [f'https://raw.githubusercontent.com/tensorflow/tensorflow/v{v}/{p}' for v in ['1.9.0','1.10.0','1.11.0','1.12.0','1.13.1','1.14.0','1.15.0'] for p in ['tensorflow/tools/api/golden/v1/tensorflow.pbtxt','tensorflow/python/ops/check_ops.py']]
urls += ['https://api.anaconda.org/package/anaconda/tensorflow','https://api.anaconda.org/package/anaconda/python','https://api.anaconda.org/package/anaconda/tensorflow-base']
def get(u):
 try:
  with urllib.request.urlopen(u,timeout=40) as r: b=r.read(); status=r.status
  d={'url':u,'http_status':status,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
  if 'pypi.org' in u:
   j=json.loads(b); d['releases']={v:[{k:x.get(k) for k in ['filename','python_version','requires_python','yanked','digests','url']} for x in j['releases'].get(v,[])] for v in ['1.9.0','1.10.0','1.11.0','1.12.0','1.13.0','1.13.0rc1','1.13.0rc2','1.13.1','1.15.0','1.15.5','2.21.0']}
  elif 'api.anaconda.org' in u:
   j=json.loads(b); vs=['3.6.13'] if '/python' in u else ['1.12.0','1.13.0','1.13.1','1.15.0']; d['releases']={v:[{k:x.get(k) for k in ['basename','version','attrs','download_url']} for x in j['files'] if x['version']==v and x['basename'].startswith('linux-64/')] for v in vs}
  else:
   t=b.decode(); d['matches']=[{'line':i,'text':l} for i,l in enumerate(t.splitlines(),1) if any(x in l for x in ['ensure_shape','name: "Session"','name: "ConfigProto"','name: "py_func"','name: "contrib"','def ensure_shape'])]; d['ensure_shape_present']='ensure_shape' in t
  return d
 except Exception as e: return {'url':u,'error':repr(e)}
res=list(concurrent.futures.ThreadPoolExecutor(max_workers=8).map(get,urls))
pathlib.Path('/tmp/m6d2a_metadata.json').write_text(json.dumps({'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'queries':res},indent=2))
for r in res:
 print(r['url'],r.get('error',r.get('http_status')), {v:len(x) for v,x in r.get('releases',{}).items()} if 'releases' in r else r.get('ensure_shape_present'))
